<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<title>Display Antrian Farmasi</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta http-equiv="Cache-Control" content="no-store, no-cache, must-revalidate">
<style>
body{font-family:'Segoe UI',sans-serif;background:linear-gradient(180deg,#27ae60,#1e8449);color:#fff;text-align:center;margin:0;overflow:hidden}body::before{content:"";background:url("../config/assets/bg_rsu.png") no-repeat center center fixed;background-size:cover;position:fixed;inset:0;opacity:.12;z-index:-1}.header{background:rgba(0,0,0,.3);padding:20px;font-size:42px;font-weight:bold;letter-spacing:2px}.status{position:fixed;top:10px;right:20px;font-size:16px;background:rgba(255,255,255,.15);padding:6px 14px;border-radius:20px;z-index:1000}.status.online{background:#2ecc71}.status.offline{background:#e74c3c}#ttsIndicator{position:fixed;top:10px;left:20px;background:rgba(0,0,0,.4);color:#fff;padding:6px 14px;border-radius:20px;font-size:15px;font-weight:500;z-index:1000;backdrop-filter:blur(4px);box-shadow:0 0 6px rgba(0,0,0,.3)}#btnSuara{position:fixed;top:60px;left:20px;background:#f1c40f;border:0;color:#2c3e50;padding:10px 20px;border-radius:10px;font-size:16px;cursor:pointer;font-weight:bold;z-index:999}#btnSuara:disabled{opacity:.6;cursor:wait}.main{display:grid;grid-template-columns:70% 30%;height:calc(100vh - 270px);gap:10px;padding:20px;box-sizing:border-box}.left{display:flex;justify-content:center;align-items:center;background:#000;overflow:hidden;border-radius:12px}.left video{width:100%;height:100%;object-fit:cover;background:#000}.right{display:flex;flex-direction:column;justify-content:space-around;align-items:center}.panel-box{background:rgba(0,0,0,.25);border-radius:20px;box-shadow:0 6px 18px rgba(0,0,0,.3);padding:30px 20px 40px;width:90%;transition:transform .2s ease}.panel-box:hover{transform:scale(1.02)}.panel-title{font-size:28px;font-weight:600;margin-bottom:10px;text-transform:uppercase;color:#ecf0f1}#noObat,#noRacikan{font-size:160px;font-weight:bold;text-shadow:4px 4px 10px rgba(0,0,0,.4);margin:0}#noObat{color:#f1c40f}#noRacikan{color:#00bfff}.label{background:#e74c3c;color:#fff;display:inline-block;margin-top:15px;padding:10px 25px;border-radius:10px;font-size:24px;box-shadow:0 5px 15px rgba(0,0,0,.3);width:fit-content;min-width:220px}.footer{position:absolute;bottom:0;width:100%;display:flex;justify-content:space-around;background:rgba(0,0,0,.25);padding:20px 0}.loket-box{background:rgba(255,255,255,.1);padding:15px;border-radius:15px;width:25%;box-shadow:0 5px 10px rgba(0,0,0,.3)}.loket-box h2{font-size:26px;margin:0;font-weight:600;color:#ecf0f1}.loket-box p{font-size:46px;margin:10px 0 0;font-weight:bold;color:#f1c40f}@keyframes heartbeat{0%{transform:scale(1);box-shadow:0 0 0 rgba(255,255,255,0)}25%{transform:scale(1.06);box-shadow:0 0 25px var(--glow-color)}50%{transform:scale(1)}75%{transform:scale(1.06);box-shadow:0 0 25px var(--glow-color)}100%{transform:scale(1)}}.heartbeat{animation:heartbeat 1.3s ease-in-out infinite}
</style>
</head>
<body>
<div id="ttsIndicator">🔊 TTS Nonaktif</div>
<button id="btnSuara">🔊 Aktifkan Suara</button>
<div class="header">ANTRIAN FARMASI PENGAMBILAN OBAT</div>
<div id="status" class="status offline">🔴 Putus koneksi</div>
<div class="main"><div class="left"><video id="tvStream" autoplay muted playsinline></video></div><div class="right"><div class="panel-box" id="boxObat"><div class="panel-title">Antrian Bukan Racikan</div><div id="noObat">---</div><div class="label" id="loketObat">Menunggu panggilan...</div></div><div class="panel-box" id="boxRacikan"><div class="panel-title">Antrian Racikan</div><div id="noRacikan">---</div><div class="label" id="loketRacikan">Menunggu panggilan...</div></div></div></div>
<div class="footer"><div class="loket-box"><h2>Loket 3</h2><p id="loket3">---</p></div><div class="loket-box"><h2>Loket 2</h2><p id="loket2">---</p></div><div class="loket-box"><h2>Loket 1</h2><p id="loket1">---</p></div></div>
<audio id="bell" src="../tingtong.mp3" preload="auto"></audio>
<script src="https://cdn.jsdelivr.net/npm/hls.js@1.7.0/dist/hls.min.js"></script>
<script>
'use strict';
const STREAM_ENABLED=<?php echo defined('ENABLE_STREAMING')&&ENABLE_STREAMING?'true':'false'; ?>;
const STREAM_URL=<?php echo json_encode(defined('STREAM_URL')?STREAM_URL:''); ?>;
const bell=document.getElementById('bell'),statusEl=document.getElementById('status'),ttsIndicator=document.getElementById('ttsIndicator'),btnSuara=document.getElementById('btnSuara'),video=document.getElementById('tvStream');
let suaraConfig=null,ttsContext=null,ttsQueue=Promise.resolve(),lastCallTime=0,sse=null,sseReconnectTimer=null,sseReconnectAttempts=0,hls=null,hlsRetryTimer=null,volumeFadeTimer=null,normalVolume=.3;
const VIDEO_VOLUME_DUCKED=.05,sessionStartTime=Math.floor(Date.now()/1000);

/* Production diagnostics: observability only. TTS flow is intentionally untouched. */
const diagnostics={
  startedAt:new Date().toISOString(),
  network:{online:navigator.onLine,lastChange:new Date().toISOString()},
  sse:{state:'idle',reconnects:0,lastOpen:null,lastEvent:null,lastError:null,lastNumber:null,lastLoket:null},
  hls:{state:STREAM_ENABLED?'idle':'disabled',retries:0,recoveries:0,lastManifest:null,lastError:null,lastPlay:null},
  queue:{lastNumber:null,lastJenis:null,lastEventTime:null},
  get snapshot(){return JSON.parse(JSON.stringify({startedAt:this.startedAt,network:this.network,sse:this.sse,hls:this.hls,queue:this.queue,uptimeSeconds:Math.floor((Date.now()-Date.parse(this.startedAt))/1000)}))}
};
window.queueDisplayDiagnostics=diagnostics;
function diagLog(type,message,data){const payload=data?Object.assign({message},data):{message};console.debug('[AntrianFarmasi]',type,payload)}
function clamp(v,min,max){return Math.min(Math.max(v,min),max)}
function updateKoneksi(ok,msg){statusEl.className='status '+(ok?'online':'offline');statusEl.textContent=ok?'🟢 Terhubung ke Server':(msg||'🔴 Putus koneksi')}
function fadeVolume(target){target=clamp(Number(target)||0,0,1);if(volumeFadeTimer){clearInterval(volumeFadeTimer);volumeFadeTimer=null}const start=Number(video.volume)||0;if(Math.abs(start-target)<.01){video.volume=target;return}const step=target>start?.05:-.05;volumeFadeTimer=setInterval(()=>{let n=Math.round((video.volume+step)*100)/100;if(step<0&&n<=target||step>0&&n>=target){n=target;clearInterval(volumeFadeTimer);volumeFadeTimer=null}video.volume=clamp(n,0,1)},100)}
async function ensureTTSContext(){try{if(!ttsContext){const A=window.AudioContext||window.webkitAudioContext;if(A)ttsContext=new A}if(ttsContext&&ttsContext.state==='suspended')await ttsContext.resume()}catch(e){console.warn('AudioContext:',e)}}
async function loadSuaraConfig(){const fallback={template_obat:'Panggilan pengambilan obat, nomor antrian {nomor}, silakan menuju ke {loket}',template_racikan:'Panggilan pengambilan obat racikan, nomor antrian {nomor}, silakan menuju ke {loket}',voice:'default',lang:'id-ID',volume:1,rate:1};try{const r=await fetch('../config/get_suara.php',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);suaraConfig=Object.assign({},fallback,await r.json())}catch(e){console.warn('Config suara gagal:',e);suaraConfig=fallback}normalVolume=clamp(Number(suaraConfig.volume)*.3,0,1);video.volume=normalVolume}
function angkaKeKata(n){const s=['','satu','dua','tiga','empat','lima','enam','tujuh','delapan','sembilan'];n=parseInt(n,10);if(isNaN(n))return'';if(n<10)return s[n];if(n<20)return n===10?'sepuluh':n===11?'sebelas':s[n-10]+' belas';if(n<100)return s[Math.floor(n/10)]+' puluh'+(n%10?' '+s[n%10]:'');if(n<200)return'seratus'+(n%100?' '+angkaKeKata(n%100):'');if(n<1000)return s[Math.floor(n/100)]+' ratus'+(n%100?' '+angkaKeKata(n%100):'');return String(n)}
function startHeartbeat(id,color){const e=document.getElementById(id);if(e){e.style.setProperty('--glow-color',color);e.classList.add('heartbeat')}}function stopHeartbeat(id){const e=document.getElementById(id);if(e)e.classList.remove('heartbeat')}
function getVoice(){if(!suaraConfig||!('speechSynthesis'in window))return null;const vs=speechSynthesis.getVoices();return vs.find(v=>v.name===suaraConfig.voice)||vs.find(v=>v.lang===suaraConfig.lang)||vs.find(v=>/^id(-|_)/i.test(v.lang))||null}
function speakText(text,box,color){return new Promise(async resolve=>{await ensureTTSContext();if(!('speechSynthesis'in window)){resolve();return}const u=new SpeechSynthesisUtterance(text);u.lang=suaraConfig.lang||'id-ID';u.volume=clamp(Number(suaraConfig.volume),0,1);u.rate=clamp(Number(suaraConfig.rate)||1,.5,2);const v=getVoice();if(v)u.voice=v;let done=false;const finish=m=>{if(done)return;done=true;stopHeartbeat(box);ttsIndicator.textContent=m||'🔊 TTS Aktif';resolve()};u.onstart=()=>{startHeartbeat(box,color);ttsIndicator.textContent='🗣️ Membaca antrian...'};u.onend=()=>finish('🔊 TTS Aktif');u.onerror=()=>finish('⚠️ Error TTS');speechSynthesis.speak(u);setTimeout(()=>finish('🔊 TTS Aktif'),15000)})}
function queueTTS(text,box,color){ttsQueue=ttsQueue.then(()=>speakText(text,box,color));ttsQueue=ttsQueue.catch(e=>{console.warn('TTS queue:',e);ttsIndicator.textContent='⚠️ Error TTS'});return ttsQueue}
function playVoice(template,nomor,loket,box,color){let nv=String(nomor||'').trim(),m=nv.match(/^([A-Za-z]+)?(\d+)$/);if(m){const p=m[1]?m[1].toUpperCase()+' ':'';nv=p+angkaKeKata(m[2].replace(/^0+/,'')||'0')}let lv=String(loket||'1').trim();if(/^\d+$/.test(lv))lv='loket '+angkaKeKata(lv);const text=String(template||'').replaceAll('{nomor}',nv).replaceAll('{loket}',lv).replace(/\bloket\s+loket\b/gi,'loket').trim();return queueTTS(text,box,color)}
function destroyHLS(){if(hls){try{hls.destroy()}catch(e){}hls=null}if(hlsRetryTimer){clearTimeout(hlsRetryTimer);hlsRetryTimer=null}}
function scheduleHLSRetry(url){if(hlsRetryTimer||!STREAM_ENABLED)return;diagnostics.hls.retries++;diagnostics.hls.state='retrying';diagLog('HLS','retry scheduled',{retries:diagnostics.hls.retries});hlsRetryTimer=setTimeout(()=>{hlsRetryTimer=null;playStream(url)},5000)}
function playStream(url){destroyHLS();if(!url||!STREAM_ENABLED){diagnostics.hls.state=STREAM_ENABLED?'error':'disabled';return}diagnostics.hls.state='connecting';diagnostics.hls.lastPlay=new Date().toISOString();if(window.Hls&&Hls.isSupported()){hls=new Hls({maxBufferLength:10,maxMaxBufferLength:20,backBufferLength:10,enableWorker:true});hls.loadSource(url);hls.attachMedia(video);hls.on(Hls.Events.MANIFEST_PARSED,()=>{diagnostics.hls.state='online';diagnostics.hls.lastManifest=new Date().toISOString();diagLog('HLS','manifest parsed');video.play().catch(()=>{})});hls.on(Hls.Events.ERROR,(ev,data)=>{if(!data||!data.fatal)return;diagnostics.hls.lastError={time:new Date().toISOString(),type:data.type,details:data.details};diagnostics.hls.state='error';diagLog('HLS','fatal error',diagnostics.hls.lastError);if(data.type===Hls.ErrorTypes.MEDIA_ERROR){diagnostics.hls.recoveries++;try{hls.recoverMediaError();diagnostics.hls.state='recovering'}catch(e){scheduleHLSRetry(url)}}else scheduleHLSRetry(url)})}else if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=url;video.addEventListener('loadedmetadata',()=>{diagnostics.hls.state='online';diagnostics.hls.lastManifest=new Date().toISOString();video.play().catch(()=>{})},{once:true});video.addEventListener('error',()=>{diagnostics.hls.state='error';diagnostics.hls.lastError={time:new Date().toISOString(),type:'native-video-error'};scheduleHLSRetry(url)},{once:true})}}
function clearSSEReconnect(){if(sseReconnectTimer){clearTimeout(sseReconnectTimer);sseReconnectTimer=null}}
function scheduleSSEReconnect(){clearSSEReconnect();sseReconnectAttempts++;diagnostics.sse.reconnects=sseReconnectAttempts;diagnostics.sse.state='reconnecting';const delay=Math.min(30000,Math.max(3000,3000*Math.pow(2,Math.min(sseReconnectAttempts-1,3))));updateKoneksi(false,`🔴 Putus koneksi — mencoba ulang dalam ${Math.ceil(delay/1000)} detik...`);diagLog('SSE','retry scheduled',{attempt:sseReconnectAttempts,delayMs:delay});sseReconnectTimer=setTimeout(()=>{sseReconnectTimer=null;connectSSE()},delay)}
function connectSSE(){clearSSEReconnect();if(sse){try{sse.close()}catch(e){}sse=null}diagnostics.sse.state='connecting';diagLog('SSE','connecting');try{sse=new EventSource('event_stream.php')}catch(e){diagnostics.sse.state='error';diagnostics.sse.lastError={time:new Date().toISOString(),message:String(e)};scheduleSSEReconnect();return}sse.onopen=()=>{sseReconnectAttempts=0;diagnostics.sse.reconnects=0;diagnostics.sse.state='online';diagnostics.sse.lastOpen=new Date().toISOString();updateKoneksi(true);diagLog('SSE','connected')};sse.onerror=()=>{diagnostics.sse.state='error';diagnostics.sse.lastError={time:new Date().toISOString(),message:'EventSource error'};diagLog('SSE','connection error');if(sse){try{sse.close()}catch(e){}sse=null}scheduleSSEReconnect()};sse.addEventListener('update',e=>{let d;try{d=JSON.parse(e.data)}catch(err){console.warn('Payload SSE tidak valid');diagnostics.sse.lastError={time:new Date().toISOString(),message:'Invalid JSON payload'};return}if(!d||!d.no)return;const t=Number(d.time)||Math.floor(Date.now()/1000),repeat=!!d.ulang;if(!repeat&&(t<sessionStartTime||t<lastCallTime))return;lastCallTime=Math.max(lastCallTime,t);const no=String(d.no),jenis=String(d.jenis||'').toLowerCase(),racikan=jenis==='racikan'||no.toUpperCase().startsWith('R'),loket=String(d.loket||'1');diagnostics.sse.lastEvent=new Date().toISOString();diagnostics.sse.lastNumber=no;diagnostics.sse.lastLoket=loket;diagnostics.queue.lastNumber=no;diagnostics.queue.lastJenis=jenis||'obat';diagnostics.queue.lastEventTime=t;diagLog('QUEUE','event received',{no,jenis:jenis||'obat',loket,time:t,repeat});bell.currentTime=0;bell.play().catch(()=>{});setTimeout(()=>{const raw=loket.trim(),label=/^loket\b/i.test(raw)?raw:'Loket '+raw;if(racikan){document.getElementById('noRacikan').textContent=no;document.getElementById('loketRacikan').textContent='Menuju '+label;playVoice(suaraConfig.template_racikan,no,loket,'boxRacikan','#00bfff')}else{document.getElementById('noObat').textContent=no;document.getElementById('loketObat').textContent='Menuju '+label;playVoice(suaraConfig.template_obat,no,loket,'boxObat','#f1c40f')}const lm=loket.match(/\d+/);if(lm){const el=document.getElementById('loket'+lm[0]);if(el)el.textContent=no}},800)})}
async function startSSE(){await loadSuaraConfig();connectSSE()}
btnSuara.addEventListener('click',async()=>{btnSuara.disabled=true;await ensureTTSContext();await loadSuaraConfig();try{await queueTTS('Inisialisasi suara','boxObat','#f1c40f');await new Promise(r=>setTimeout(r,700));await queueTTS('Suara aktif','boxObat','#f1c40f');ttsIndicator.textContent='🔊 TTS Aktif';btnSuara.style.display='none';startSSE()}catch(e){btnSuara.disabled=false;ttsIndicator.textContent='⚠️ Gagal mengaktifkan suara'}});
window.addEventListener('online',()=>{diagnostics.network.online=true;diagnostics.network.lastChange=new Date().toISOString();diagLog('NETWORK','online');if(STREAM_ENABLED)playStream(STREAM_URL);if(!sse)connectSSE()});window.addEventListener('offline',()=>{diagnostics.network.online=false;diagnostics.network.lastChange=new Date().toISOString();diagLog('NETWORK','offline');updateKoneksi(false,'🔴 Jaringan offline')});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){diagLog('PAGE','visible');if(STREAM_ENABLED&&video.paused)video.play().catch(()=>{});if(!sse)connectSSE()}});
document.addEventListener('DOMContentLoaded',async()=>{await loadSuaraConfig();if(STREAM_ENABLED)playStream(STREAM_URL);diagLog('PAGE','initialized',{streamEnabled:STREAM_ENABLED})});
window.addEventListener('beforeunload',()=>{clearSSEReconnect();if(sse){try{sse.close()}catch(e){}}destroyHLS();if(volumeFadeTimer)clearInterval(volumeFadeTimer);try{speechSynthesis.cancel()}catch(e){}});
</script>
</body>
</html>
